// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Chromatic Communication"

Composer is a trigger-based sound generator invented by Yota Morimoto.
I asked him for permission to use it in one of my shaders in November
2023, and he gladly agreed. In its original version, the notes are
generated from diatonic scales. However, the theme for this challenge
required a chromatic scale. So, I generate an array of 12 consecutive
integers for the algorithm to choose from, which does not necessarily
sound great. In the spirit of providing a richer and more pleasing
overall composition, the set scale is a choice I made. All diatonic
scales and the chromatic one are in the code, so you can try any of
them. I have left a few more comments in the code in order to invite
you to play with it.

The shader uses a layer technique to blend the three different
aspects, the background, the rays and the foreground. The animation
should give the impression that the motifs in the foreground are the
result of the rays of light that feed the colors. 

The first shader I used Dr. Morimoto's Audio Signal Generator for:
https://codepen.io/atzedent/details/wvNxpEJ

The Audio Signal Generator by Yota Morimoto:
https://yota.tehis.net/asg/
*/

var choose = a => a[Math.floor(Math.random() * a.length)]
var speeds = [0.4, 0.2, 0.1]
var resont = [0.6, 0.8, 0.85]
var volmns = [1]
var options = {
  volume: choose(volmns),
  resonance: choose(resont),
  speed: choose(speeds)
}

var Composer = () => {

  /** @type {AudioContext} */
  let context,
    main, verb, bus, compressor

	// The types of trigger
  const trigger = Object.freeze({
    trig: function () {
      let prev = 0
      let t = false
      return function (val) {
        t = prev < 0 && val >= 0
        prev = val
        return t
      }
    },
    change: function () {
      let prev = 0
      let t = false
      return function (val) {
        t = prev != val
        prev = val
        return t
      }
    },
    pulse: function (threshold) {
      let prev = 0
      let t = false
      return function (b) {
        if (b) prev++
        if (prev == threshold) {
          t = true
          prev = 0
        } else { t = false }
        return t
      }
    },
    every: function (n) {
      let i = 0
      return () => i++ % n === 0
    }
  })

	// Create triggers
  const lowTrig = trigger.trig()
  const bassTrig = trigger.trig()
  const lowChanged = trigger.change()
  const bassChanged = trigger.change()
  const highChanged = trigger.change()
  const pulseTrig = trigger.trig()
  const every4th = trigger.every()
  const pulsed = trigger.pulse(10)
	// the roots of the scales (together with the scales the function
	// midicps converts this to a note based on A4)
	const roots = [21, 23, 24, 26, 28, 30]
	// diatonic scales
	const melodicminor = [0, 2, 3, 5, 7, 9, 11]
  const locrian = [0, 1, 3, 5, 6, 8, 10]
  const phrygian = [0, 1, 3, 5, 7, 8, 10]
  const aeolian = [0, 2, 3, 5, 7, 8, 10]
  const dorian = [0, 2, 3, 5, 7, 9, 10]
  const ionian = [0, 2, 4, 5, 7, 9, 11]
  const mixolydian = [0, 2, 4, 5, 7, 9, 10]
  const lydian = [0, 2, 4, 6, 7, 9, 11]
	// the chromatic scale
	const chromatic = Float32Array.from({ length: 12 }, (v, k) => k) 
	// my choice (which is not even a scale)
	const mychoice = [0, 4, 0, 9, 0, 4, 9]
	// the scale to use
  let m = mychoice
	// initialize a random number array
  let b = Float32Array.from({ length: 3 }, () => Math.random() * 2 - 1)
	// pick a root at random
  let root = pickItem(b[1], 0, 20, roots)
	// set the random value for the shader
  options.rand = lerp(b[2], -1, 1, 0.05, 1)

  function loop() {
    main.gain.value = dbamp(lerp(options.volume, 0, 1, -60, 3))
    compose()
    setTimeout(() => loop(), expInterp(options.speed, 0, 1, 800, 80))
  }

  function compose() {
		// re-initialize the random number array, this time not with 3 but 24 values.
		// There are many ways to generate random values. Here are two to choose from:
    //b = Float32Array.from({ length: 24 }, () => Math.random() < .25 ? Math.random() * 2 - 1 : 0)
    b = brownNoise(24, 0.25, 1).map(p => Math.random() < 0.25 ? lerp(p, 0, 1, -1, 1) : p)
		// if the trigger fires, re-initialize the roots, shuffle the speed and print the 
		// resulting settings to the console.
    if (pulsed(pulseTrig(b[0]))) {
      root = pickItem(b[1], 0, 20, [21, 25, 28, 33])
      options.speed = choose(speeds)
      console.table(options)
    }
		// play a note if the lowTrig trigger fires
    if (lowTrig(b[21])) {
      const note = pickNote(b[21], 15, 35)
      if (lowChanged(note)) {
				// use the triangle wave
        tri(
          midicps(note),
          pickVolume(b[22], -24, -9),
          b[23]
        )
      }
    }
		// play a note if the picked note is different than the one picked before
    /*if (pulsed())*/ {
      const note = pickNote(b[11], 20, 32)
      if (highChanged(note)) {
				// use the triangle wave
        tri(
          midicps(note),
          pickVolume(b[12], -24, -24),
          b[13]
        )
      }
			// play a note every 4th time the algorithm passes here
      if (every4th()) {
				// use the sine wave
        sine(
          midicps(pickNote(b[11], 5, 15)),
          pickVolume(b[12], -30, -25),
          b[13]
        )
      }
    }
		// play a note if the bassTrig trigger fires
    if (bassTrig(b[11])) {
      const note = pickNote(b[11], 5, 15)
      if (bassChanged(note)) {
				// use the sine wave
        sine(
          midicps(note),
          pickVolume(b[12], -30, -9),
          b[13]
        )
				// use the sawtooth wave
        saw(
          midicps(note),
          pickVolume(b[13], -30, -25),
          b[12]
        )
      }
    }
  }

  function pickItem(v, a, b, array) {
    return array[round(lerp(v, -1, 1, a, b)) % (array.length - 1)]
  }

  function pickNote(v, a, b) {
    return deg2key(lerp(v, -1, 1, a, b), m) + root
  }

  function pickVolume(v, a, b) {
    return dbamp(lerp(v, -1, 1, a, b))
  }

  function mod(n, m) { return ((n % m) + m) % m }

  function div(a, b) { return a / b >> 0 }

  function deg2key(degree, mode) {
    const size = mode.length
    const deg = round(degree)
    return (12 * div(deg, size)) + mode[mod(deg, size)]
  }

  function expInterp(x, a, b, c, d) {
    if (x <= a) {
      return c
    }
    if (x >= b) {
      return d
    }
    return Math.pow(d / c, (x - a) / (b - a)) * c
  }

  function lerp(x, a, b, c, d) {
    if (x <= a) {
      return c
    }
    if (x >= b) {
      return d
    }
    return (x - a) * (d - c) / (b - a) + c
  }

  function round(a) { return (a + (a > 0 ? 0.5 : -0.5)) << 0 }

  function midicps(a) { return 440 * Math.pow(2, (a - 69) * 0.083333333333) }

  function dbamp(a) { return Math.pow(10, a*5e-2) }

  function createReverb(context) {
    const length = 6 * context.sampleRate
    const decay = 0.8
    const buffer = context.createBuffer(2, length, context.sampleRate)
    const noiseData = [buffer.getChannelData(0), buffer.getChannelData(1)]

    const noise = Float32Array.from({ length }, () => Math.random() * 2 - 1)

    for (i = 0; i < length; i++) {
      const k = noise[i]
      noiseData[0][i] = k * Math.pow(1 - i / length, decay)
      noiseData[1][i] = k * Math.pow(1 - i / length, decay)
    }

    const convolver = context.createConvolver()
    convolver.buffer = buffer

    return convolver
  }

  function init() {
    window.AudioContext = window.AudioContext || window.webkitAudioContext || window.mozAudioContext || window.oAudioContext
    context = new AudioContext({ latencyHint: 'balanced' })

    verb = createReverb(context)
    compressor = context.createDynamicsCompressor()
    main = context.createGain()
    bus = context.createGain()
    bus.connect(verb)
    verb.connect(main)
    main.connect(compressor)
    compressor.ratio.value = 24
    compressor.release.value = 0.5
    compressor.threshold.value = -26
    compressor.connect(context.destination)

		// Print the current settings to the console
    console.table(options)

		// reduce pressure at the first render
    requestAnimationFrame(loop)
  }
  function instrument(freq, amp, pan, type, att, rel, detune) {
    const HALF_PI = Math.PI * 0.5
    const vco = context.createOscillator()
    const vca = context.createGain()
    const out = context.createGain()
    const panner = context.createStereoPanner()
    panner.pan.value = pan
    vco.detune.value = detune
    vco.type = type //triangle, sine, square, sawtooth, custom
    vco.frequency.value = freq

    const filter = context.createBiquadFilter()
    filter.type = "allpass"
    filter.frequency.value = 392
    filter.Q.value = 2
    filter.gain.value = 8

    // lfo
    const lfo = context.createOscillator()
    const lfoAmp = context.createGain()
    lfo.type = type
    lfo.frequency.value = 6
    lfoAmp.gain.value = 12

    lfo.connect(lfoAmp)
    lfoAmp.connect(filter.frequency)

    // xfade resonance
    out.gain.value = Math.cos(options.resonance * HALF_PI)
    bus.gain.value = Math.cos((1 - options.resonance) * HALF_PI)
    vco.connect(filter)
    filter.connect(vca)
    vca.connect(panner)
    panner.connect(out)
    out.connect(main)
    panner.connect(bus)
    // env
    const now = context.currentTime
    const attack = now + att
    const release = attack + rel
    vca.gain.value = 0.003
    vca.gain.setValueAtTime(vca.gain.value, now)
    vca.gain.linearRampToValueAtTime(amp, attack)
    vca.gain.exponentialRampToValueAtTime(0.001, release)

    lfo.start(now)
    vco.start(now)

    // gc
    lfo.stop(release + 0.1)
    vco.stop(release + 0.1)
    setTimeout(() => { lfo.disconnect(); vco.disconnect() }, 1000 * (release + 0.2))
  }

  function sine(freq, amp, pan) {
    instrument(freq, amp, pan, 'sine', 0.1 + lerp(b[2], -1, 1, 0, 0.2), 0.125 + lerp(b[3], -1, 1, 0, 0.1), 5)
  }

  function tri(freq, amp, pan) {
    instrument(freq, amp, pan, 'triangle', 0.01, 0.125, 5)
  }

  function sqr(freq, amp, pan) {
    instrument(freq, amp, pan, 'square', 0.01, 0.5, 5)
  }

  function saw(freq, amp, pan) {
    instrument(freq, amp, pan, 'sawtooth', 0.025, 0.85, Math.sqrt(freq))
  }

  function brownNoise(n, h, scale) {
    let result = []
    let delta = 1 / n
    let hurst = Math.pow(2, 2 * h - 2)

    let b = [Math.random() * scale]

    for (i = 1; i < n; i++) {
      let rnd = Math.sqrt(delta) * (Math.random() - 0.5) * scale
      b[i] = b[i - 1] + rnd
    }

    for (i = 0; i < n; i++) {
      let idx = Math.floor(i * hurst) % n
      result.push((b[idx] % scale + scale) % scale)
    }

    return result
  }
  init()
}

var theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr
var canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr
  resizeCanvas(ww, wh)
	const canvas = document.querySelector('canvas')
	canvas.style = canvasStyle
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2487199/files/vert.glsl', 'frag.glsl')
}

function setup() {
  pixelDensity(1)
  createCanvas(ww, wh, WEBGL)
	const canvas = document.querySelector('canvas')
	canvas.style = canvasStyle
	Composer()
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader)

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height])
  theShader.setUniform("time", millis() / 1000.0)
	theShader.setUniform("startRandom", options.rand)

  // rect gives us some geometry on the screen
  rect(0,0,width,height)
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) || this.canvas.getContext('experimental-webgl', this._pInst._glAttributes)
	if (this.drawingContext === null) throw new Error('Error creating webgl context')
	else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL)
		gl.viewport(0, 0, ww, wh)
		this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
	}
}
